/**
 * Kiswahili dictionary (W4-I18N) — real, respectful Kenyan Kiswahili.
 *
 * Honesty rules (spec §62 "don't hard-code user-facing strings" + this wave's
 * no-garbage-translation policy):
 *  · Construction/business jargon that Kenyan sites genuinely use in English
 *    stays English (Finder, Data Saver, PPE, MRs/POs, feature flags, session,
 *    command palette, Quantity Surveyor, "Muster Line").
 *  · Product names never translate (MjengoOS, AI Copilot, M-Pesa, WhatsApp).
 *  · Every key in en.ts exists here and vice-versa (compile-time assert in
 *    dicts/check.ts; runtime dev guard validateDicts() in the provider).
 */
